from Decimal import Decimal
from collections import defaultdict


def analyze(data, plan):
    kind = plan["kind"]
    group_by = plan.get("group_by")
    start = plan.get("start")
    end = plan.get("end")
    amount_source = plan.get("amount_source")
    included = set(plan.get("included_statuses") or [])

    # 客户 → 州
    cust_state = {}
    for c in data.get("customers", []):
        cust_state[c["customer_id"]] = c["customer_state"]

    # 每单金额（分）
    order_amount = defaultdict(int)
    if amount_source == "payments":
        for p in data.get("order_payments", []):
            order_amount[p["order_id"]] += int(p["payment_value_cents"] or 0)
    else:
        for it in data.get("order_items", []):
            order_amount[it["order_id"]] += int(it["price_cents"] or 0) + int(it["freight_cents"] or 0)

    def in_period(t):
        if not t:
            return False
        if start is not None and t < start:
            return False
        if end is not None and t >= end:
            return False
        return True

    total_count = 0
    total_amount = 0
    groups = defaultdict(lambda: {"order_count": 0, "amount_cents": 0})

    for o in data.get("orders", []):
        if o["order_status"] not in included:
            continue
        t = o["order_status"] and o.get("order_purchase_timestamp") or ""
        if not in_period(t):
            continue
        oid = o["order_id"]
        amt = order_amount.get(oid, 0)
        total_count += 1
        total_amount += amt
        if group_by == "customer_state":
            g = cust_state.get(o.get("customer_id"), "unknown")
        elif group_by == "purchase_date":
            g = t[:10]
        elif group_by == "purchase_month":
            g = t[:7]
        else:
            g = None
        if g is not None:
            groups[g]["order_count"] += 1
            groups[g]["amount_cents"] += amt

    rows = []
    if group_by is not None:
        for g, v in groups.items():
            row = {"group": g, "order_count": v["order_count"], "amount_cents": v["amount_cents"]}
            if kind == "share":
                row["share"] = ratio(v["amount_cents"], total_amount)
            rows.append(row)
        if kind == "ranking":
            rows.sort(key=lambda r: (-r["amount_cents"], r["group"]))
        else:
            rows.sort(key=lambda r: r["group"])

    result = {
        "kind": kind,
        "total": {"order_count": total_count, "amount_cents": total_amount},
        "rows": rows,
    }
    return result
